<?php

declare(strict_types=1);

namespace ItechWorld\SuluTailwindThemeBundle\Media;

/**
 * Where an image comes from, as the editor declares it in the media library.
 *
 * The two AI values follow the EU icons for labelling AI-generated content
 * (AI Act, article 50): content fully generated by AI, and human-made
 * content partially modified with AI.
 */
enum ImageOrigin: string
{
    case Human = 'human';
    case AiModified = 'ai_modified';
    case AiGenerated = 'ai_generated';

    /**
     * @param mixed $value A stored or submitted value
     *
     * @return self The origin it names, a human one for anything unknown
     */
    public static function fromValue(mixed $value): self
    {
        return \is_string($value) ? (self::tryFrom($value) ?? self::Human) : self::Human;
    }

    /**
     * @return bool True when the image has to carry an AI label
     */
    public function isAi(): bool
    {
        return self::Human !== $this;
    }
}
